('ielts-b4-spk1-001', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part1', 'Introduction', 'Baking', 'Have you ever baked a cake or a loaf of bread? Did anyone in your family bake when you were a child? Why do you think so many people enjoy baking? Give natural answers with relevant detail. This is a short Part 1 practice drill, not a complete 4–5 minute interview.', 90, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
