('ielts-b4-spk2-001', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Relative You Enjoy Spending Time With', 'Describe a relative you enjoy spending time with. You should say: who this relative is; how often you see each other; what you do together; and explain why you enjoy spending time with this relative. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-002', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Person Who Is Good at Cooking', 'Describe a person you know who is good at cooking. You should say: how you know this person; what dishes they cook; how they learned to cook; and explain what you think of their cooking. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
