('ielts-b4-spk2-004', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Sportsperson You Admire', 'Describe a sportsperson you admire. You should say: who this sportsperson is; which sport they play; how you first heard about them; and explain why you admire this sportsperson. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
