('ielts-b4-spk2-007', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Musician or Singer You Like', 'Describe a musician or singer you like. You should say: who the musician or singer is; what kind of music they perform; how you first heard their music; and explain why you like their music. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-008', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Café You Often Go To', 'Describe a café that you often go to. You should say: where the café is; what food and drink it serves; what you usually do there; and explain why you like this café. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-009', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Library or Bookshop You Like', 'Describe a library or bookshop that you like. You should say: where the library or bookshop is; what it looks like inside; how often you visit it; and explain why you like going there to read or browse. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-010', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Place Where You Do Exercise', 'Describe a place where you go to do sport or exercise. You should say: where it is; what facilities it has; who you usually go with; and explain why you like exercising there. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-011', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Hotel You Stayed In', 'Describe a hotel you have stayed in. You should say: where the hotel was; why you stayed there; what the rooms and service were like; and explain whether you would recommend the hotel. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-012', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Small Town or Village You Visited', 'Describe a small town or village you have visited. You should say: where the town or village is; why you went there; what you saw and did; and explain what you liked or disliked about this town or village. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-013', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Museum or Gallery You Visited', 'Describe a museum or art gallery you went to. You should say: where the museum or gallery is; what kind of things are on display; who you went with; and explain what you found most interesting in the museum or gallery. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-014', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Traditional Dish From Your Country', 'Describe a traditional dish from your country. You should say: what the dish is; how it is made; when people usually eat it; and explain why people in your country like this dish. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-015', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A City You Enjoyed Visiting', 'Describe a city you enjoyed visiting. You should say: which city it was; who you went with; which places you visited in the city; and explain why you enjoyed your time in this city. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-016', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Piece of Furniture You Like', 'Describe a piece of furniture that you like. You should say: what it is; where it is; how long you have had it; and explain why you like this piece of furniture. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-017', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'An Old Object Your Family Has Kept', 'Describe an old object that your family has kept for many years. You should say: what the object is; where it came from; where it is kept now; and explain why your family has kept it. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-018', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'An Invention You Think Is Important', 'Describe an invention that you think is important. You should say: what the invention is; when it was invented; how people use it; and explain why you think this invention is important. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-019', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'Something You Carry Every Day', 'Describe an item that you carry with you every day. You should say: what the item is; how long you have had it; what you use it for; and explain why you always take it with you. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-020', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Musical Instrument You Would Like to Play', 'Describe a musical instrument you would like to be able to play. You should say: what the instrument is; where you have heard it played; how you could learn; and explain why you would like to play this instrument. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-021', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'Something You Are Saving Up For', 'Describe something you are saving money to buy. You should say: what it is; how much it costs; how you are saving for it; and explain why you want to buy it. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-022', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Tree or Plant You Like', 'Describe a tree or plant that you like. You should say: what the tree or plant is; where you have seen it; what it looks like in different seasons; and explain why you like this tree or plant. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-023', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Night You Spent Outdoors', 'Describe a time when you spent a night outdoors, for example on a camping trip. You should say: where you were; who you were with; what you did; and explain how you felt about sleeping outside. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-024', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Birthday Celebration You Remember', 'Describe a birthday celebration you remember well. You should say: whose birthday it was; where the celebration took place; what people did; and explain why you remember this birthday. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-025', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Live Performance You Enjoyed', 'Describe a live performance you enjoyed, such as a concert, a play or a dance show. You should say: what the performance was; where and when you saw it; who you went with; and explain why you enjoyed the performance. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-026', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Time You Got Lost', 'Describe a time when you got lost. You should say: where you were; how you got lost; how you found your way; and explain how you felt while you were lost. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-027', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Mistake You Learned From', 'Describe a mistake you made that taught you something. You should say: what the mistake was; when you made it; what effect it had; and explain what you learned from this mistake. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-028', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Time Someone Praised You', 'Describe a time when someone praised you for something you had done. You should say: who praised you; what you had done; what they said; and explain how you reacted to the praise. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-029', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'Something You Did for the First Time', 'Describe something you did for the first time recently. You should say: what you did; when and where you did it; why you decided to do it; and explain how you felt about doing it. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-030', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Disagreement You Had With Someone', 'Describe a time when you disagreed with someone. You should say: who the other person was; what you disagreed about; how the disagreement ended; and explain how you felt once it was over. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-031', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Time You Had to Decide Quickly', 'Describe a time when you had to make a decision very quickly. You should say: what the situation was; what you decided; what happened next; and explain whether you think your quick decision was correct. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-032', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Holiday You Would Like to Take', 'Describe a holiday you would like to take in the future. You should say: where you would go; who you would take with you; what you would like to see and do; and explain why you would choose this holiday. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-033', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Meal You Cooked for Other People', 'Describe a meal you cooked for other people. You should say: what you cooked; who you cooked it for; why you cooked it; and explain how the meal went. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-034', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Visit to Someone''s Home', 'Describe a visit you made to a friend''s or relative''s home. You should say: whose home it was; why you went there; what you did during the visit; and explain what you enjoyed most about being a guest. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-035', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Day You Spent Alone', 'Describe a day when you spent most of the time on your own. You should say: which day it was; why you were alone; how you spent your time; and explain how you felt about being on your own. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-036', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Talk or Presentation You Gave', 'Describe a talk or presentation you gave. You should say: what the talk was about; who the audience was; how you prepared for it; and explain how nervous you felt before and during the talk. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-037', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'Something You Looked Forward To', 'Describe something you looked forward to for a long time. You should say: what it was; why you were looking forward to it; what happened when it finally came; and explain whether it was as good as you had expected. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-038', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A School Trip You Remember', 'Describe a school trip you remember. You should say: where you went; how old you were; what you did during the trip; and explain why you remember this trip. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-039', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A TV Programme You Often Watch', 'Describe a television programme you often watch. You should say: what the programme is called; what it is about; when it is on; and explain why you like this programme. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-040', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'An Article You Read', 'Describe an interesting article you read in a newspaper, a magazine or online. You should say: what the article was about; where you read it; what new information it gave you; and explain why the article caught your attention. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-041', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Game You Played as a Child', 'Describe a game you played when you were a child. You should say: what the game was; who you played it with; how you played it; and explain why you enjoyed playing this game. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-042', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Subject You Enjoyed at School', 'Describe a subject you enjoyed studying at school. You should say: which subject it was; who taught it; what you did in the lessons; and explain why you enjoyed this subject. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-043', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Time You Were Stuck in Traffic', 'Describe a time when you were stuck in traffic. You should say: where you were going; why the traffic was so bad; what you did while you were waiting; and explain how you felt about the delay. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-044', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Company You Would Like to Work For', 'Describe a company you would like to work for. You should say: what the company is; what it does; how you found out about the company; and explain why you would like to work there. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-045', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Pet You Remember', 'Describe a pet that you or someone you know had. You should say: what kind of animal it was; who it belonged to; what it was like; and explain why you remember this pet. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-046', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'An Invitation You Accepted', 'Describe an invitation you received and accepted. You should say: who invited you; what the invitation was for; how you were invited; and explain why you accepted it. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-047', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Well-Designed Everyday Object', 'Describe an everyday object that you think is well designed. You should say: what the object is; what people use it for; where you can buy one; and explain what makes it so well designed. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-048', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'Something You Found That Belonged to Someone Else', 'Describe a time when you found something that belonged to someone else. You should say: what you found; where you found it; how you returned it to its owner; and explain how you felt about what happened. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-049', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'A Bicycle Ride You Remember', 'Describe a bicycle ride you remember. You should say: where you rode; who you were with; what you saw along the route; and explain why you remember this ride. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk2-050', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'An Early Childhood Memory', 'Describe one of your earliest memories. You should say: how old you were; where you were; what happened; and explain why you think this memory has stayed so clear. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-001', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Grandparents and Grandchildren', 'What can grandparents teach their grandchildren? Do grandparents play a bigger or smaller part in family life than they did in the past? Should grandparents be expected to look after children while the parents are at work? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-002', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Fast Food and Convenience', 'Why has fast food become so popular? Should fast food restaurants be allowed near schools? Will people cook less at home as ready meals become cheaper? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-003', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Creativity in Schools', 'Can creativity be taught, or are some people simply born creative? Do schools give enough time to subjects such as art and music? Which jobs need creative people most? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-004', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Sports Stars and Young People', 'Why do young people admire sports stars? Should famous athletes be expected to set a good example? Does watching top athletes encourage children to be more active? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-005', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Humour and Comedy', 'Why do people from different countries find different things funny? Is humour useful in the workplace? Are there subjects that people should not joke about? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-006', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Music and Young People', 'Why is music so important to many teenagers? Should every child learn to play a musical instrument at school? How has the way people listen to music changed? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-007', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Cafés and Meeting Places', 'Why have cafés become such popular places to meet? Do people need public places where they can meet without spending money? How are the places where young people meet different from those older people prefer? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-008', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'The Future of Bookshops', 'Why do some people still prefer to buy books in a shop? Can small bookshops compete with large online sellers? Do you think printed books will ever disappear? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-009', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Public Sports Facilities', 'Should sports centres and swimming pools be free to use? What sports facilities does a town need? Why do some people stop exercising as they get older? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-010', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Working in Tourism', 'What are the advantages and disadvantages of working in the tourist industry? Why do some hotels offer better service than others? How does tourism create jobs in a local area? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-011', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Village Life', 'What are the advantages of growing up in a small village? Is life in a village less stressful than life in a city? How could villages be made more attractive places for families? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-012', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Buying Second-Hand Goods', 'Why do some people prefer to buy second-hand things? Are there any products that people should always buy new? Has the internet made it easier to buy and sell used items? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-013', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Keeping Old Things', 'Why do families keep old objects that they no longer use? Should old objects be kept even when they are no longer useful? Do young people value old things as much as their grandparents? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-014', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Inventions and Progress', 'Which invention of the last hundred years has changed people''s lives the most? Do all new inventions make life better? Should governments pay for scientific research or leave it to private companies? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-015', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Skilled Manual Work', 'Why do fewer young people train as plumbers, electricians or builders? Should manual jobs be paid as well as office jobs? Is it more useful to learn a trade than to go to university? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-016', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Saving and Spending', 'Why do some people find it hard to save money? Should children be given pocket money? Is it more sensible to save money or to spend it on experiences? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-017', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Camping and Outdoor Holidays', 'Why do some families choose camping holidays? Is camping becoming more or less popular in your country? What effects do large numbers of visitors have on the countryside? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-018', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Celebrating Birthdays', 'Why do people celebrate birthdays? Do parents spend too much money on children''s birthday parties? Are some birthdays more important than others in your culture? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-019', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Live Music and Theatre', 'Why do people pay to see live performances when recordings are available? Should theatres and concert halls receive government money? How can young people be encouraged to go to the theatre? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-020', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Maps and Navigation Technology', 'How has satellite navigation changed the way people travel? Is it still important to be able to read a paper map? Do people depend too much on their phones for directions? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-021', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Learning From Mistakes', 'Why are some people afraid of making mistakes? Should teachers let students make mistakes? Is it easier for children or adults to admit that they were wrong? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-022', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Praise and Motivation', 'Is it important for parents to praise their children? Can too much praise be harmful? Apart from money, what makes people want to work hard? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-023', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Trying New Experiences', 'Why do some people enjoy trying new things more than others? Are young people more willing to take risks than older people? Should schools encourage shy students to try new hobbies? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-024', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Arguments and Disagreements', 'What do people in families most often argue about? Is it sometimes good for people to disagree? How can people settle a disagreement without getting angry? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-025', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Quick Decisions', 'What important decisions do young people have to make? Is it better to make decisions quickly or to take time to think? Should people ask others for advice before making big decisions? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-026', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Types of Holiday', 'Why do some people prefer package holidays to organising their own trip? Is it better to go on holiday in your own country or abroad? How have people''s holidays changed since your parents were young? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-027', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Hospitality and Guests', 'How do people in your country usually welcome guests? Is it more common now to meet friends in cafés than to invite them home? Is it acceptable to arrive at someone''s home without an invitation? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-028', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Spending Time Alone', 'Why do some people enjoy being alone? Is it good for children to spend some time on their own? Do people who live alone feel lonely more often than others? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-029', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Public Speaking', 'Why are many people nervous about speaking in public? Should schools teach students how to give presentations? Which jobs require good speaking skills? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-030', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Learning Outside the Classroom', 'What can students learn on school trips that they cannot learn in class? Should school trips be paid for by parents or by the school? Are museums and galleries good places for children to learn? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-031', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'The Future of Television', 'Do people watch less television than they did in the past? Is television a good way for children to learn? Will people still sit down together to watch the same television channel? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-032', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Newspapers and Magazines', 'Why are fewer people buying newspapers? Is news on the internet as reliable as news in print? What kinds of magazines are still popular? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-033', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Traditional Games', 'Why are some traditional children''s games disappearing? Do children today play differently from children in the past? Should parents limit the time children spend on screens? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-034', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'The School Curriculum', 'Which subjects should all children study at school? Should students be allowed to choose their subjects at a young age? Should practical skills such as cooking and managing money be part of every curriculum? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-035', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Long Commutes', 'Why do some people accept a long journey to work? How does commuting affect people''s quality of life? Should employers let staff start and finish work at different times to avoid the rush hour? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-036', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Choosing an Employer', 'What makes a company a good employer? Do most people prefer to work for large companies or small ones? Should companies be judged on how they treat the environment? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-037', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Keeping Pets', 'Why do people keep pets? Is having a pet good for children? Should there be rules about keeping pets in flats? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-038', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Social Occasions', 'Why do people sometimes turn down invitations? Are formal social occasions less common than they used to be? How has technology changed the way people invite others to events? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-039', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Honesty', 'Is it always wrong to tell a lie? Do you think most people would hand in something valuable they had found? How can parents teach children to be honest? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-040', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Cycling in Cities', 'Why do more people cycle in some cities than in others? Should cities build more cycle lanes, even if it means less space for cars? Is cycling safe for children in your town? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-041', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Memory and Remembering', 'Why do people remember some events clearly and forget others? Do people today need to remember as much as people did in the past? What can older people do to keep their memory good? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-042', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Free Public Transport', 'Should public transport be free for everyone? Who benefits most from cheap buses and trains? Why do many people still prefer to drive? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-043', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Robots in the Home', 'What household jobs could robots do in the future? Would you trust a robot to look after an elderly relative? Could robots in the home make people lazy? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-044', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'High-Rise Living', 'What are the advantages of living in a tall block of flats? Are high-rise buildings a good solution to housing shortages? Should every new block of flats have a playground and a garden? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-045', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Zoos and Wildlife Parks', 'Should zoos still exist? Do zoos help to protect endangered animals? Is it better for children to see animals in zoos or in documentaries? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-046', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Politeness and Manners', 'Are good manners less important than they used to be? Do manners differ from country to country? Should schools teach manners, or is that the job of parents? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-047', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Packaging and Waste', 'Why do many products have so much packaging? Should shops be made to reduce plastic packaging? Are people in your country willing to change their shopping habits to reduce waste? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-048', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'A Cashless Society', 'Why are people using cash less than before? Who might find it difficult if cash disappeared completely? Do people spend more when they pay by card? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-049', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Siblings and Family Size', 'How does having brothers and sisters affect a child? Why are families smaller today than they were in the past? Do the oldest children in a family usually have more responsibility? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking']),
('ielts-b4-spk3-050', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part3', 'Speaking Part 3 (Discussion)', 'Forests and Woodland', 'Why are forests important? Should trees be cut down to make space for new homes? How can children learn to value the natural world? Discuss reasons, comparisons and examples. This is a two-minute discussion drill; a full examiner-led Part 3 lasts 4–5 minutes.', 120, 0, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking'])
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-11', 'Shopping and money', '{"part1": [{"topic": "where you grew up", "questions": ["Where did you grow up?", "What was it like to live there as a child?", "Has it changed much since then?"]}, {"topic": "clothes", "questions": ["What kind of clothes do you usually wear?", "Do you enjoy shopping for clothes?", "Have your tastes in clothes changed as you have got older?"]}], "part2": {"topic": "a disappointing purchase", "cue": "Describe something you bought that you were not happy with.", "points": ["what you bought", "where and when you bought it", "what was wrong with it"], "explain": "and explain what you did about it.", "rounding": "Do you usually take back things that you are not happy with?"}, "part3": {"topic": "shopping and consumers", "questions": ["Why do people sometimes buy things they later regret?", "How can shoppers protect themselves from poor-quality products?", "Are online reviews useful when you are deciding what to buy?", "Should shops always accept goods that customers want to return?", "How have shopping habits in your country changed in recent years?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-12', 'Science and discovery', '{"part1": [{"topic": "your course or job", "questions": ["Are you studying or working at the moment?", "Which part of your course or job do you find most interesting?", "Is there anything you find difficult about it?"]}, {"topic": "the sky", "questions": ["Do you often look up at the sky?", "Can you see the stars clearly where you live?", "Did you learn anything about the planets when you were at school?"]}], "part2": {"topic": "an interesting scientific discovery", "cue": "Describe a scientific discovery or a piece of science news that you found interesting.", "points": ["what the discovery or news was", "how you heard about it", "what you know about it"], "explain": "and explain why you found it interesting.", "rounding": "Did you talk to anyone else about it?"}, "part3": {"topic": "science and society", "questions": ["Why do some children lose interest in science as they get older?", "Is it more important to spend money on medical research or on space research?", "How can scientists explain their work to ordinary people?", "Should the results of scientific research be free for everyone to read?", "What do you think will be the most important scientific discovery of the next fifty years?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-13', 'Languages and understanding', '{"part1": [{"topic": "where you live now", "questions": ["Who do you live with at the moment?", "What is the best thing about the area you live in?", "How long do you plan to stay there?"]}, {"topic": "films", "questions": ["What kind of films do you enjoy?", "Do you prefer watching films at home or at the cinema?", "Do you ever watch films with subtitles?"]}], "part2": {"topic": "communicating without a shared language", "cue": "Describe a time when you had to communicate with someone who did not speak your language.", "points": ["who the person was", "where you met them", "how you managed to understand each other"], "explain": "and explain how you felt about the experience.", "rounding": "Has anything like this happened to you since?"}, "part3": {"topic": "language and communication", "questions": ["Why do people learn foreign languages?", "Is it rude to visit a country without learning a few words of its language?", "How much can people communicate using gestures and body language?", "Will translation apps ever be as good as a human interpreter?", "Should English be the main language of international business?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-14', 'Rules and responsibilities', '{"part1": [{"topic": "your job", "questions": ["What job do you do?", "What do you do on a typical working day?", "Would you like to be doing the same job in ten years?"]}, {"topic": "housework", "questions": ["Which household jobs do you do?", "Did you have to help at home when you were a child?", "Is there any housework you really dislike?"]}], "part2": {"topic": "a responsibility you have had", "cue": "Describe a responsibility you have had, at home, at school or at work.", "points": ["what the responsibility was", "when you had it", "what you had to do"], "explain": "and explain how you felt about having this responsibility.", "rounding": "Do you still have this responsibility now?"}, "part3": {"topic": "responsibility", "questions": ["At what age should young people be allowed to make their own decisions?", "Why do some people avoid taking responsibility at work?", "Should parents be held responsible for the behaviour of their children?", "What responsibilities do companies have towards their local community?", "Are people today more or less responsible than their grandparents were?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-15', 'Sport and teams', '{"part1": [{"topic": "your street", "questions": ["What is the street where you live like?", "Do you know the people who live on your street?", "Is your street busy or quiet?"]}, {"topic": "photographs", "questions": ["Do you take a lot of photographs?", "What do you usually take photographs of?", "Do you prefer to keep photographs on your phone or to print them?"]}], "part2": {"topic": "a sports team", "cue": "Describe a sports team that you support or know about.", "points": ["what the team is", "how you learned about it", "how well the team has done recently"], "explain": "and explain why you are interested in this team.", "rounding": "Have you ever seen this team play live?"}, "part3": {"topic": "team sports and competition", "questions": ["What can children learn from playing team sports?", "Why do people feel so strongly about the teams they support?", "Should schools give more time to sport?", "Is winning the most important thing in sport?", "Why do some sports get more attention on television than others?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-16', 'Weather and seasons', '{"part1": [{"topic": "your flat or house", "questions": ["How many rooms are there in your home?", "Which room do you spend most time in?", "Is your home easy to keep warm in winter?"]}, {"topic": "going out in the evening", "questions": ["How often do you go out in the evening?", "Where do people in your town go in the evening?", "Do you prefer going out or staying in?"]}], "part2": {"topic": "a day of perfect weather", "cue": "Describe a day when the weather was perfect for what you were doing.", "points": ["when it was", "what the weather was like", "what you were doing"], "explain": "and explain why the weather made the day special.", "rounding": "Is weather like this common where you live?"}, "part3": {"topic": "weather and seasons", "questions": ["Why do many people prefer one season to another?", "How do the seasons affect what people eat and wear?", "Why do some people move to countries with a warmer climate?", "Should schools close when the weather is very hot or very cold?", "How might the seasons in your country be different in fifty years?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-17', 'Homes and living space', '{"part1": [{"topic": "your city", "questions": ["Which city do you live in?", "What do visitors usually want to see there?", "What would you change about your city if you could?"]}, {"topic": "shoes", "questions": ["How many pairs of shoes do you own?", "Do you prefer comfortable shoes or fashionable ones?", "Where do you usually buy your shoes?"]}], "part2": {"topic": "a room you like in another home", "cue": "Describe a room in someone else''s home that you like.", "points": ["whose home it is", "what the room looks like", "what people do in it"], "explain": "and explain why you like this room.", "rounding": "Would you like to have a room like this in your own home?"}, "part3": {"topic": "homes and living space", "questions": ["What makes a home comfortable?", "Why do people in some countries live in smaller homes than people elsewhere?", "Is it better to rent a home or to buy one?", "How have homes in your country changed over the last thirty years?", "Should young adults leave their parents'' home as soon as they can afford to?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-18', 'Habits and change', '{"part1": [{"topic": "what you do", "questions": ["Are you working or studying at the moment?", "What part of it do you find most enjoyable?", "Where would you like to be working in five years?"]}, {"topic": "breakfast", "questions": ["What did you have for breakfast today?", "Do you eat breakfast at the same time every day?", "Is breakfast at the weekend different from breakfast on weekdays?"]}], "part2": {"topic": "a habit you would like to change", "cue": "Describe a habit you have that you would like to change.", "points": ["what the habit is", "when you started it", "why you have not been able to change it yet"], "explain": "and explain why you would like to change it.", "rounding": "Do people close to you have the same habit?"}, "part3": {"topic": "habits and routines", "questions": ["Why is it so hard for people to break bad habits?", "Do habits formed in childhood last for life?", "Can technology help people to build better habits?", "Are daily routines good for people, or do they make life dull?", "Is it easier to start a good habit or to stop a bad one?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-19', 'Uniforms and dress', '{"part1": [{"topic": "your family", "questions": ["How many people are there in your family?", "What do you usually do together as a family?", "Who are you most similar to in your family?"]}, {"topic": "colours", "questions": ["What colour do you wear most often?", "Are there any colours you would never wear?", "Do colours have special meanings in your country?"]}], "part2": {"topic": "a uniform you have worn", "cue": "Describe a uniform you have had to wear, for example for school or a job.", "points": ["what the uniform looked like", "when you wore it", "how you felt wearing it"], "explain": "and explain whether you think wearing it was a good idea.", "rounding": "Do you still have this uniform?"}, "part3": {"topic": "uniforms and dress codes", "questions": ["Why do many schools make students wear a uniform?", "What do the clothes people wear to work say about them?", "Should employees be allowed to wear whatever they like to work?", "Why do some jobs require a uniform?", "Are people judged too much on their appearance?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-20', 'Planning and organising', '{"part1": [{"topic": "your favourite place in your town", "questions": ["Where is your favourite place in your town?", "How often do you go there?", "Do you usually go there alone or with other people?"]}, {"topic": "writing lists", "questions": ["Do you ever write shopping lists or lists of things to do?", "Do you write lists on paper or on your phone?", "Do you think making lists helps people to organise their lives?"]}], "part2": {"topic": "an event you helped to organise", "cue": "Describe an event that you helped to organise.", "points": ["what the event was", "who you organised it with", "what you did to prepare for it"], "explain": "and explain whether the event was a success.", "rounding": "Would you like to organise another event like this?"}, "part3": {"topic": "planning and organising", "questions": ["Why are some people better at organising things than others?", "Is it better to plan every detail of a holiday or to leave some things to chance?", "What skills does a person need to organise a large event?", "Should schools teach young people how to plan their time?", "Do people plan their lives further ahead than they used to?"]}}'::jsonb, (SELECT greatest(now(), max(created_at)) FROM speaking_mock_sets) + interval '1 second') ON CONFLICT (id) DO NOTHING;
